-- Image observations use the existing diary and body measurement domains.
ALTER TABLE meal_entries ALTER COLUMN product_id DROP NOT NULL;
ALTER TABLE meal_entries ADD COLUMN observed_name TEXT;
ALTER TABLE meal_entries ADD CONSTRAINT meal_entries_product_or_observation CHECK (product_id IS NOT NULL OR observed_name IS NOT NULL);
ALTER TABLE meal_entries ADD COLUMN meal_group_id UUID;
ALTER TABLE meal_entries ADD COLUMN source_update_id BIGINT REFERENCES telegram_updates(update_id) ON DELETE SET NULL;
ALTER TABLE meal_entries ADD COLUMN source_message_id BIGINT;
ALTER TABLE meal_entries ADD COLUMN source_item_index INT;
ALTER TABLE meal_entries ADD COLUMN correlation_id TEXT;
ALTER TABLE meal_entries ADD COLUMN source_file_unique_id TEXT;
CREATE UNIQUE INDEX meal_entries_image_source_unique ON meal_entries(user_id, source_update_id, source_item_index)
  WHERE source_update_id IS NOT NULL;

ALTER TABLE body_measurements ADD COLUMN source_update_id BIGINT REFERENCES telegram_updates(update_id) ON DELETE SET NULL;
ALTER TABLE body_measurements ADD COLUMN source_message_id BIGINT;
ALTER TABLE body_measurements ADD COLUMN correlation_id TEXT;
ALTER TABLE body_measurements ADD COLUMN source_file_unique_id TEXT;
CREATE UNIQUE INDEX body_measurements_image_source_unique ON body_measurements(user_id, source_update_id)
  WHERE source_update_id IS NOT NULL;

CREATE UNIQUE INDEX workout_increments_image_source_unique ON workout_ingestion_increments(telegram_update_id)
  WHERE telegram_update_id IS NOT NULL AND operation = 'image_machine_metrics';


ALTER TABLE products ADD COLUMN nutrition_source TEXT;
ALTER TABLE products ADD COLUMN source_barcode TEXT;
ALTER TABLE products ADD COLUMN source_values_basis TEXT;
ALTER TABLE products ADD COLUMN source_update_id BIGINT REFERENCES telegram_updates(update_id) ON DELETE SET NULL;
ALTER TABLE products ADD COLUMN source_message_id BIGINT;
ALTER TABLE products ADD COLUMN correlation_id TEXT;
ALTER TABLE products ADD COLUMN source_file_unique_id TEXT;
CREATE UNIQUE INDEX products_image_source_unique ON products(owner_id,source_update_id) WHERE source_update_id IS NOT NULL;

CREATE TABLE telegram_media_groups (
 user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 media_group_id TEXT NOT NULL,
 first_update_id BIGINT REFERENCES telegram_updates(update_id) ON DELETE SET NULL,
 PRIMARY KEY(user_id,media_group_id)
);

-- Bring the existing admin prompt editor's versioned fields into the schema.
ALTER TABLE system_prompts ADD COLUMN IF NOT EXISTS version INT NOT NULL DEFAULT 1;
ALTER TABLE system_prompts ADD COLUMN IF NOT EXISTS content TEXT;
ALTER TABLE system_prompts ADD COLUMN IF NOT EXISTS description TEXT;
ALTER TABLE system_prompts ADD COLUMN IF NOT EXISTS model TEXT NOT NULL DEFAULT '';
UPDATE system_prompts SET content=template WHERE content IS NULL;
ALTER TABLE system_prompts ALTER COLUMN content SET NOT NULL;
INSERT INTO system_prompts(key,template,content,description) VALUES ('image_classification',$vision$Ты — визуальный маршрутизатор персонального фитнес-ассистента. Определи по изображению, подписи и контексту правильный workflow. Не записывай ничего и не придумывай невидимые данные.
Категории: food — готовая еда, продукты, напиток; nutrition_label — основная цель фото таблица пищевой ценности, состав или штрихкод упаковки; gym_machine_display — экран тренажёра с показателями; scale — весы с измерением; body_progress — фото тела для отслеживания прогресса; fitness_equipment — оборудование без экрана результатов; document — программа, таблица или расписание; other — распознаваемое другое; unknown — недостаточно информации.
Если упаковка лишь видна рядом с едой, выбирай food. Если видны показатели экрана, выбирай gym_machine_display. Не делай медицинских выводов. Верни только JSON: {"type":"food","confidence":0.94,"evidence":["видна еда"],"requires_clarification":false}.$vision$,$vision$Ты — визуальный маршрутизатор персонального фитнес-ассистента. Определи по изображению, подписи и контексту правильный workflow. Не записывай ничего и не придумывай невидимые данные.
Категории: food — готовая еда, продукты, напиток; nutrition_label — основная цель фото таблица пищевой ценности, состав или штрихкод упаковки; gym_machine_display — экран тренажёра с показателями; scale — весы с измерением; body_progress — фото тела для отслеживания прогресса; fitness_equipment — оборудование без экрана результатов; document — программа, таблица или расписание; other — распознаваемое другое; unknown — недостаточно информации.
Если упаковка лишь видна рядом с едой, выбирай food. Если видны показатели экрана, выбирай gym_machine_display. Не делай медицинских выводов. Верни только JSON: {"type":"food","confidence":0.94,"evidence":["видна еда"],"requires_clarification":false}.$vision$,'Vision workflow') ON CONFLICT(key) DO NOTHING;
INSERT INTO system_prompts(key,template,content,description) VALUES ('food_image_analysis',$vision$Ты — эксперт-диетолог и специалист по визуальному анализу пищи. Определи все видимые продукты, оцени массу по видимому масштабу; если референса нет, используй типичный размер посуды 22–25 см. Для смешанного блюда оцени ингредиенты, если можно, иначе укажи "mixed dish". Игнорируй несъедобные предметы. Оценки КБЖУ приблизительны. Ответь только валидным JSON без пояснений: {"items":[{"name_ru":"Название","name_en":"Name","weight_g":150,"calories":220,"protein_g":12.5,"fat_g":5,"carbs_g":30,"confidence":"low"}],"total":{"calories":220,"protein_g":12.5,"fat_g":5,"carbs_g":30},"notes":"Краткая неопределённость"}. Все числа — number, не строки.$vision$,$vision$Ты — эксперт-диетолог и специалист по визуальному анализу пищи. Определи все видимые продукты, оцени массу по видимому масштабу; если референса нет, используй типичный размер посуды 22–25 см. Для смешанного блюда оцени ингредиенты, если можно, иначе укажи "mixed dish". Игнорируй несъедобные предметы. Оценки КБЖУ приблизительны. Ответь только валидным JSON без пояснений: {"items":[{"name_ru":"Название","name_en":"Name","weight_g":150,"calories":220,"protein_g":12.5,"fat_g":5,"carbs_g":30,"confidence":"low"}],"total":{"calories":220,"protein_g":12.5,"fat_g":5,"carbs_g":30},"notes":"Краткая неопределённость"}. Все числа — number, не строки.$vision$,'Vision workflow') ON CONFLICT(key) DO NOTHING;
INSERT INTO system_prompts(key,template,content,description) VALUES ('nutrition_label_analysis',$vision$Ты анализируешь пищевую этикетку. Извлеки только напечатанные данные: название, бренд, штрихкод, массу упаковки и порции, основу значений (per_100g/per_serving/per_package/unknown), калории и БЖУ, ингредиенты. Если значение не читается, null. Не оценивай самостоятельно, если есть таблица производителя. Если КБЖУ нет, но продукт распознан, needs_web_lookup=true. Ответь только JSON: {"product_name":null,"brand":null,"barcode":null,"package_weight_g":null,"serving_size_g":null,"values_basis":"unknown","calories":null,"protein_g":null,"fat_g":null,"carbs_g":null,"ingredients":[],"needs_web_lookup":false,"confidence":0.0}.$vision$,$vision$Ты анализируешь пищевую этикетку. Извлеки только напечатанные данные: название, бренд, штрихкод, массу упаковки и порции, основу значений (per_100g/per_serving/per_package/unknown), калории и БЖУ, ингредиенты. Если значение не читается, null. Не оценивай самостоятельно, если есть таблица производителя. Если КБЖУ нет, но продукт распознан, needs_web_lookup=true. Ответь только JSON: {"product_name":null,"brand":null,"barcode":null,"package_weight_g":null,"serving_size_g":null,"values_basis":"unknown","calories":null,"protein_g":null,"fat_g":null,"carbs_g":null,"ingredients":[],"needs_web_lookup":false,"confidence":0.0}.$vision$,'Vision workflow') ON CONFLICT(key) DO NOTHING;
INSERT INTO system_prompts(key,template,content,description) VALUES ('nutrition_ingredient_estimate',$vision$Ты оцениваешь приблизительную пищевую ценность продукта только по читаемому составу, когда нет таблицы КБЖУ и не найден надёжный источник. Порядок ингредиентов приблизительно соответствует убыванию массы. Не выдавай оценку за данные производителя. Верни только JSON: {"calories":null,"protein_g":null,"fat_g":null,"carbs_g":null,"confidence":0.0}. Значения на 100 г; confidence не выше 0.4.$vision$,$vision$Ты оцениваешь приблизительную пищевую ценность продукта только по читаемому составу, когда нет таблицы КБЖУ и не найден надёжный источник. Порядок ингредиентов приблизительно соответствует убыванию массы. Не выдавай оценку за данные производителя. Верни только JSON: {"calories":null,"protein_g":null,"fat_g":null,"carbs_g":null,"confidence":0.0}. Значения на 100 г; confidence не выше 0.4.$vision$,'Vision workflow') ON CONFLICT(key) DO NOTHING;
INSERT INTO system_prompts(key,template,content,description) VALUES ('gym_machine_display_analysis',$vision$Ты анализируешь экран спортивного тренажёра. Извлеки только видимые показатели. Не определяй тип тренажёра только по цифрам. machine_hint допускается лишь если корпус или подпись ясно показывают тип. Сохраняй исходные единицы; приложение переводит miles и mph. Верни только JSON: {"machine_hint":null,"duration_text":null,"duration_seconds":null,"distance_value":null,"distance_unit":"","distance_km":null,"speed_value":null,"speed_unit":"","speed_kmh":null,"calories":null,"heart_rate_bpm":null,"resistance":null,"level":null,"incline_percent":null,"watts":null,"rpm":null,"steps":null,"floors":null,"strokes":null,"repetitions":null,"load_kg":null,"confidence":0.0}. Для нечитаемого null.$vision$,$vision$Ты анализируешь экран спортивного тренажёра. Извлеки только видимые показатели. Не определяй тип тренажёра только по цифрам. machine_hint допускается лишь если корпус или подпись ясно показывают тип. Сохраняй исходные единицы; приложение переводит miles и mph. Верни только JSON: {"machine_hint":null,"duration_text":null,"duration_seconds":null,"distance_value":null,"distance_unit":"","distance_km":null,"speed_value":null,"speed_unit":"","speed_kmh":null,"calories":null,"heart_rate_bpm":null,"resistance":null,"level":null,"incline_percent":null,"watts":null,"rpm":null,"steps":null,"floors":null,"strokes":null,"repetitions":null,"load_kg":null,"confidence":0.0}. Для нечитаемого null.$vision$,'Vision workflow') ON CONFLICT(key) DO NOTHING;
INSERT INTO system_prompts(key,template,content,description) VALUES ('scale_analysis',$vision$Ты анализируешь фото весов. Извлеки только видимые числовые измерения; не выводи состав тела по внешности. Если единица lb, верни поле weight_lb и weight_kg=null: приложение выполнит перевод. Ответь только JSON: {"weight_kg":null,"weight_lb":null,"body_fat_percent":null,"muscle_mass_kg":null,"water_percent":null,"visceral_fat":null,"bmi":null,"confidence":0.0}.$vision$,$vision$Ты анализируешь фото весов. Извлеки только видимые числовые измерения; не выводи состав тела по внешности. Если единица lb, верни поле weight_lb и weight_kg=null: приложение выполнит перевод. Ответь только JSON: {"weight_kg":null,"weight_lb":null,"body_fat_percent":null,"muscle_mass_kg":null,"water_percent":null,"visceral_fat":null,"bmi":null,"confidence":0.0}.$vision$,'Vision workflow') ON CONFLICT(key) DO NOTHING;
INSERT INTO system_prompts(key,template,content,description) VALUES ('equipment_image_analysis',$vision$Назови видимый спортивный тренажёр или оборудование и его обычное назначение. Не утверждай, что пользователь на нём тренировался. Ответь только JSON: {"name":"","purpose":"","confidence":0.0}.$vision$,$vision$Назови видимый спортивный тренажёр или оборудование и его обычное назначение. Не утверждай, что пользователь на нём тренировался. Ответь только JSON: {"name":"","purpose":"","confidence":0.0}.$vision$,'Vision workflow') ON CONFLICT(key) DO NOTHING;
INSERT INTO system_prompts(key,template,content,description) VALUES ('document_image_analysis',$vision$Кратко перескажи читаемое фитнес-содержание документа по-русски. Не записывай тренировку и не додумывай нечитаемые фрагменты. Ответь обычным текстом, 1–3 предложения.$vision$,$vision$Кратко перескажи читаемое фитнес-содержание документа по-русски. Не записывай тренировку и не додумывай нечитаемые фрагменты. Ответь обычным текстом, 1–3 предложения.$vision$,'Vision workflow') ON CONFLICT(key) DO NOTHING;
INSERT INTO system_prompts(key,template,content,description) VALUES ('other_image_analysis',$vision$Кратко и по-русски ответь на подпись пользователя с учётом фото. Если задача неясна, спроси, что сделать с фото. Не делай диагнозов и не утверждай невидимое. Ответь обычным текстом.$vision$,$vision$Кратко и по-русски ответь на подпись пользователя с учётом фото. Если задача неясна, спроси, что сделать с фото. Не делай диагнозов и не утверждай невидимое. Ответь обычным текстом.$vision$,'Vision workflow') ON CONFLICT(key) DO NOTHING;
